"use strict";
module.exports = /*#__PURE__*/JSON.parse('{"header":{"home":"Home","about":"About Me","techs":"Techs & Skills","projects":"Projects","contact":"Contact"},"pageTitles":{"home":"Home","about":"About Me","projects":"Projects","contact":"Contact","cv":"Resume","projectDetail":"Project"},"home":{"hero":"Turning ideas into code, purpose into projects, and innovation into impact.","heroTypewriterDesktop":["Turning ideas into code,","Purpose into projects and innovation into impact.","Full Stack Developer focused on results.","Accessibility, impact and purpose guiding every line of code."],"heroTypewriterMobile":["Full Stack Dev in action.","Technology with purpose.","Real impact, clean code."]},"welcome":"Welcome to my portfolio!","name":"Amaro V S Júnior","role":"Full Stack Developer specialized in Front End","location":"Atibaia, São Paulo, Brazil","phone":"Phone: +55 11 96075 7716","linkedin":"LinkedIn","github":"GitHub","profileSectionTitle":"Professional Profile","profile":"Full Stack Developer focused on creating modern, accessible solutions with real impact. Experienced in React, Node.js, TypeScript, and DevOps. Committed to quality deliveries, continuous learning, and collaboration in diverse projects.","about":{"title":"About Me","body":"I\'m Amaro Valerio da Silva Júnior, 42 years old, born on 09/17/1981, from Atibaia, Brazil. I\'m the son of Maria Edleusa Monção da Silva, brother to Milca, Samuel (in memoriam), Azenate, and Zaine, and a proud uncle of seven nephews and nieces.\\n\\nThe most profound experience of my life has been taking daily care of my mother, who suffered a stroke 13 years ago. This routine goes far beyond practical tasks: I prepare special meals, assist her mobility, manage medication, take her to medical appointments, keep her company, and handle every small adaptation to guarantee her comfort, safety, and dignity. I also took on this role with my father and my brother before they passed away, which completely changed my perspective on empathy, resilience, and humanity.\\n\\nI started my career in HR/Payroll but had to reinvent myself to take care of my family. I found a new opportunity in technology: I completed the Full Stack course at Kenzie Academy and am now studying Systems Analysis and Development (ADS) at Uniasselvi. I carry strong values learned at home: honesty, empathy, and the mission to make people\'s lives easier through my work.\\n\\nToday, I balance production work in a factory, digital media at Assembleia de Deus church, freelance jobs, and work as an analyst in the Linkando.dev project. I master modern stacks such as React, Node.js, TypeScript, Tailwind CSS, MongoDB, Docker, REST API, Next.js, Express, and CSS. I\'m especially proud of projects like EcoVoz (accessibility) and Autismo Tech 2024, which show the power of technology to promote inclusion.\\n\\nOutside the dev world, I am passionate about working out, taking care of my mother with love, watching movies, series, doramas, traveling, enjoying beaches, waterfalls, and good coffee. I love music—from jazz to black music, including R&B, pop, and blues. Between code and care, I believe that purpose, technology, and empathy can change the world.","instagram":"Follow my Instagram","carouselTitle":"Moments from My Journey","carouselFooter":"See more on my Instagram!","dotLabel":"Go to photo {{n}}","prev":"Previous photo","next":"Next photo","seeTechs":"See my full stack"},"techs":{"title":"Techs & Skills","intro":"Check out the main technologies, frameworks, and tools I master and use in my projects:","skillsList":["HTML5","CSS3","SASS","Tailwind CSS","JavaScript","TypeScript","React","Next.js","Redux","Vite","styled-components","Node.js","Express","Spring Boot","Django","PostgreSQL","MongoDB","Docker","Git","GitHub","REST API","VSCode","Figma","Windows"],"desc":{"html5":"Markup language for structuring web pages.","css3":"Stylesheet language for designing interfaces.","javascript":"Dynamic programming language for the web.","typescript":"Typed superset of JavaScript for scalable applications.","react":"JS library for building modern interfaces.","nextjs":"React framework for SSR/SSG and full stack apps.","nodejs":"JavaScript runtime for backend development.","express":"Minimal framework for Node.js APIs.","redux":"Global state management for React apps.","vite":"Super fast bundler for modern projects.","springboot":"Java framework for microservices and APIs.","django":"Python framework for robust, fast web apps.","postgresql":"Advanced open source relational database.","mongodb":"NoSQL database oriented to documents.","docker":"Application and environment containerization.","git":"Distributed version control.","github":"Git repository hosting and collaboration.","tailwindcss":"Utility-first CSS framework for responsive UI.","sass":"CSS preprocessor with advanced features.","styledcomponents":"CSS-in-JS for React components.","figma":"Collaborative UI/UX design tool.","windows":"The most widely used desktop OS."}},"education":"Education","skills":"Skills","experience":"Professional Experience","projectsSection":"Relevant Projects","projectsLabel":"Projects","certs":"Certifications","idioms":"Languages","educations":[{"title":"Rocketseat ONE (In Progress)","date":"September/2024 - Present","desc":"Full Stack course including React.js, Node.js, JavaScript, TypeScript, DevOps, and AI. Development of complete applications, use of DevOps tools and AI.","link":"https://www.rocketseat.com.br/"},{"title":"Kenzie Academy Brasil","date":"September/2023 - September/2024","desc":"Full Stack course focused on React.js, Node.js, PostgreSQL, Python. Over 2000h of practical learning in software from front-end to back-end.","link":"https://kenzie.com.br/"},{"title":"UNIASSELVI - Systems Analysis and Development (In Progress)","date":"July/2024 - December/2026","desc":"Training in programming fundamentals, software engineering, databases, and agile methodologies.","link":"https://portal.uniasselvi.com.br/"}],"experiences":[{"title":"Freelance Web Developer","date":"July/2024 - Present","bullets":["Development of web solutions using React, JavaScript, and TailwindCSS to create modern and dynamic interfaces.","Creation of responsive interfaces, ensuring accessibility and a smooth user experience across devices.","Use of Git for version control in collaborative projects, ensuring consistency and traceability.","Development of projects such as an e-commerce platform and task management system.","Experience in remote work and effective client communication for requirements gathering."]},{"title":"Singular Serviços de Saúde Ltda","date":"HR Analyst - August/2012 to July/2017","bullets":["Payroll management and process automation, resulting in greater operational efficiency.","Supervision of benefits and compliance with labor legislation, ensuring employee satisfaction.","Communication with stakeholders and improvements in internal department processes."]},{"title":"WM Assistência Contábil","date":"Payroll Assistant - February/2010 to April/2011","bullets":["Handling admissions, terminations, and vacation calculations, focusing on process optimization.","Improvement of analytical and process management skills."]}],"projectsSectionArr":[{"title":"Kenzie Hub","desc":"Portfolio platform for developers to add and manage technologies they are learning, focused on showcasing professional growth.","stack":"Technologies: React, Context API, TypeScript.","link":"https://kenzie-hub-seven-blue.vercel.app/"},{"title":"Control Finance","desc":"Personal finance management app to register incomes and expenses, view total balance, and filter transactions by category.","stack":"Technologies: React, Tailwind CSS.","link":"https://control-finance-react-tail-wind.vercel.app/"}],"skillsArr":["Front-End: React, HTML, CSS, JavaScript, TailwindCSS, Styled Components, API integration","Back-End: Node.js, Express, PostgreSQL, Python, Django REST Framework","Tools: Git, GitHub, Vercel, Figma, Docker","Others: Responsive design, Hooks, OOP, TDD, Scrum, Kanban, DevOps"],"certificationsArr":["NLW Rocketseat - Intermediate Full-Stack: Certification in back-end application development with Node.js, REST API concepts, using TypeScript, Fastify, DrizzleORM, PostgreSQL, Docker, and Zod. Also includes front-end development with ReactJS using modern concepts.","Kenzie Academy - Completion Certificate: 2000 hours in Full-Stack Programming, covering HTML, CSS, React.js, TypeScript, Node.js, PostgreSQL, Python, focused on complete and scalable applications.","Kenzie Academy - Completion Certificate: 1000 hours in Front-End Programming with HTML, CSS, React.js, TypeScript, with a strong emphasis on modern development practices and creating responsive and intuitive user interfaces."],"idiomsArr":["Portuguese: Native","English: Intermediate (studying, focused on reading and conversation fluency)","Spanish: Advanced (skills in reading, writing, and verbal communication in professional settings)"],"button":{"seeMore":"See more","print":"Print / Save PDF","downloadPdf":"Download PDF"},"projects":{"title":"Projects by Category","metaDescription":"Main projects in Full Stack, Front End development and real solutions. See cases of technology, social impact and innovation.","categories":{"fullStack":"Full Stack","frontEnd":"Front End"},"imgAlt":"Project image {{name}}","stack":"Technologies","demo":"Demo","github":"GitHub"},"featured_projects":"Featured Projects","see_repo":"See repository","see_all_on_github":"See all on GitHub","demo":"Demo","loading":"Loading...","error":"Error loading GitHub projects.","all":"All","no_description":"No description...","backToProjects":"Back to Projects","contact":{"title":"Let\'s Work Together","subtitle":"Have a project in mind or just want to say hello? Fill out the form below and I\'ll get back to you as soon as possible.","form":{"firstName":"First Name","lastName":"Last Name","email":"Email Address","phone":"Phone Number","message":"Write your message here...","button":"Send Message"},"infoTitle":"Contact Information","phone":"Phone","email":"Email","address":"Address","addressText":"Atibaia, São Paulo, Brazil","toast":{"success":"Message sent successfully!","error":"Error sending message. Please try again."}},"cv":{"title":"Resume"},"footer":{"rights":"All rights reserved."}}');

